B.c7=new A.AI("Requiere atenci\xf3n",B.li,1,"atencion")
B.N4=s(["calor","frio","sol","playa"],t.s)
B.Dt=new A.cx("temperatura","","Temperatura fuera de rango","La bomba est\xe1 demasiado fr\xeda o demasiado caliente para funcionar con seguridad. La insulina tambi\xe9n se degrada con el calor.",B.LY,B.c7,B.N4)
B.MP=s(['Ejecuta "Llenar c\xe1nula" con las unidades que indique la caja de tu cat\xe9ter.',"Excepci\xf3n: en agujas de acero (Sure-T, TruSteel) NO se llena c\xe1nula."],t.s)
B.NN=s(["cebar","purgar","llenar canula","aire"],t.s)
B.De=new A.cx("cateter_sin_llenar","","C\xe1nula sin llenar","Has terminado el recambio pero no se ha completado el llenado de la c\xe1nula, as\xed que hay aire en el tramo final y no est\xe1 entrando insulina.",B.MP,B.c7,B.NN)
B.M2=s(["Confirma con una glucemia capilar.","Trata la hipoglucemia si se confirma.","La basal se reanuda sola al recuperarte; tambi\xe9n puedes reanudarla manualmente."],t.s)
B.KO=s(["hipo","suspension","smartguard","parada por baja"],t.s)
B.Dk=new A.cx("suspension_nivel_bajo","bmedtronic","Suspensi\xf3n por nivel bajo","El sensor ha detectado glucosa baja y la bomba ha suspendido autom\xe1ticamente la administraci\xf3n de basal.",B.M2,B.c7,B.KO)
B.Od=s(["Confirma con glucemia capilar.","No hace falta tomar hidratos si a\xfan est\xe1s en rango: la suspensi\xf3n es preventiva.","Vigila la evoluci\xf3n los siguientes 30 minutos."],t.s)
B.NU=s(["prediccion","preventiva","smartguard"],t.s)
B.Dv=new A.cx("suspension_antes_bajo","bmedtronic","Suspensi\xf3n antes de nivel bajo","El sensor predice que vas a bajar y la bomba ha suspendido la basal de forma preventiva.",B.Od,B.eb,B.NU)
B.LT=s(["Comprueba que el sensor est\xe1 dando lecturas.","Sigue las indicaciones de la pantalla para volver a modo autom\xe1tico.","Mientras est\xe9s en manual, vigila m\xe1s de cerca tu glucosa."],t.s)
B.M_=s(["modo manual","smartguard","automatico","auto mode"],t.s)
B.Dh=new A.cx("salida_modo_auto","bmedtronic","Salida del modo autom\xe1tico","La bomba ha vuelto a modo manual, normalmente por falta de lecturas del sensor o porque lleva demasiado tiempo administrando la basal m\xe1xima o m\xednima.",B.LT,B.c7,B.M_)
B.MJ=s(['Retira el reservorio y repite "Nueva configuraci\xf3n" desde el principio.',"Comprueba que el reservorio est\xe1 bien encajado y girado hasta el tope.","Si el error se repite, llama al soporte del fabricante."],t.s)
B.Mq=s(["error carga","piston","rebobinar"],t.s)
B.Dz=new A.cx("error_carga","bmedtronic","Error de carga / Error de administraci\xf3n","La bomba no ha podido completar la carga del reservorio o el movimiento del pist\xf3n.",B.MJ,B.c7,B.Mq)
B.NG=s(["Desactiva el Pod desde el Controlador y ret\xedralo.","Coloca un Pod nuevo cuanto antes.",u.u],t.s)
B.KD=s(["caducado","expirado","pod viejo"],t.s)
B.Dq=new A.cx("pod_caducado","bomnipod","Pod caducado","El Pod ha superado su vida \xfatil y ha dejado de administrar insulina.",B.NG,B.cV,B.KD)
B.NR=s(["Desactiva el Pod desde el Controlador y ret\xedralo de la piel.","Coloca un Pod nuevo.","Guarda el Pod defectuoso: el soporte puede ped\xedrtelo.","M\xeddete la glucosa y comprueba cetonas."],t.s)
B.LU=s(["pitido","alarma continua","fallo pod"],t.s)
B.Ds=new A.cx("pod_error","bomnipod","Error del Pod / Alarma de peligro","El Pod ha detectado un fallo interno y ha detenido la administraci\xf3n. Suele ir acompa\xf1ado de un pitido continuo.",B.NR,B.cV,B.LU)
B.KM=s(["Acerca el Controlador al Pod, a menos de un palmo.","Si sigue sin desactivarse, usa la opci\xf3n de descartar el Pod del Controlador.","Retira el Pod de la piel manualmente y ponte uno nuevo."],t.s)
B.ND=s(["no desactiva","no se apaga","quitar pod"],t.s)
B.Do=new A.cx("pod_desactivar","bomnipod","No se puede desactivar el Pod","El Controlador no consigue comunicarse con el Pod para desactivarlo.",B.KM,B.c7,B.ND)
B.LN=s(["Acerca el Controlador al Pod.","Al\xe9jate de fuentes de interferencia.","Si no se recupera, el Pod seguir\xe1 con su \xfaltima basal: planifica el recambio."],t.s)
B.NM=s(["sin se\xf1al pod","no conecta","fuera de alcance"],t.s)
B.Dm=new A.cx("pod_comunicacion","bomnipod","Sin comunicaci\xf3n con el Pod","El Controlador no encuentra el Pod. El Pod sigue administrando la basal que ten\xeda programada.",B.LN,B.c7,B.NM)
B.O0=s(["Sustituye el cartucho siguiendo el proceso de recambio.","Recuerda cebar el cat\xe9ter tras poner el cartucho nuevo.","M\xeddete la glucosa."],t.s)
B.M0=s(["cartucho","vacio","sin insulina"],t.s)
B.Df=new A.cx("cartucho_vacio_ypso","bypsopump","Cartucho vac\xedo","La YpsoPump ha llegado al final del cartucho y ha detenido la administraci\xf3n.",B.O0,B.cV,B.M0)
B.KN=s(["Comprueba que la hora y la fecha son correctas.","Revisa que tu perfil basal sigue activo.","Comprueba la insulina activa: puede haberse perdido el registro."],t.s)
B.NT=s(["reinicio","se reinicio","error software"],t.s)
B.Di=new A.cx("reinicio_bomba","btandem","Reinicio de la bomba","La bomba se ha reiniciado tras un error de software. Algunos ajustes pueden requerir confirmaci\xf3n.",B.KN,B.c7,B.NT)
B.MR=s(["Acerca el receptor o el m\xf3vil al sensor.","Comprueba que el transmisor est\xe1 bien encajado, si tu modelo lo lleva.","Reinicia el Bluetooth del dispositivo y espera 15 minutos.","Mide con glucemia capilar mientras no haya lecturas."],t.s)
B.Mf=s(["no conecta","sin se\xf1al","bluetooth","sin lecturas"],t.s)
B.Dj=new A.cx("senal_perdida","","P\xe9rdida de se\xf1al del sensor","El dispositivo no recibe lecturas del sensor. La bomba sigue administrando tu basal, pero sin ajuste autom\xe1tico.",B.MR,B.c7,B.Mf)
B.MB=s(["Retira el sensor y coloca uno nuevo.","Consulta la gu\xeda de recambio de sensor de esta app.","Recuerda que hay un periodo de calentamiento antes de las primeras lecturas."],t.s)
B.MO=s(["caducado","expirado","fin de vida","cambiar sensor"],t.s)
B.Dl=new A.cx("sensor_caducado","","Sensor caducado / Cambiar sensor","El sensor ha llegado al final de su vida \xfatil y ha dejado de medir.",B.MB,B.eb,B.MO)
B.Mx=s(["L\xe1vate y s\xe9cate bien las manos antes de pincharte.","Introduce el valor capilar en cuanto lo obtengas.","No calibres si tu glucosa est\xe1 cambiando r\xe1pido: espera a un momento estable."],t.s)
